refentry.refsect1:
&reftitle.description;
public static Time\DurationTime\Duration::fromNanoseconds intnanoseconds
Creates a non-negative duration of nanoseconds nanoseconds. The value is normalized into whole seconds and nanoseconds, see the Time\Duration::$seconds and Time\Duration::$nanoseconds properties.

&reftitle.parameters;
nanoseconds
The number of nanoseconds. Must be greater than or equal to 0.

&reftitle.errors;



   If nanoseconds is negative, a
   ValueError is thrown.

  &reftitle.examples;

   Time\Duration::fromNanoseconds example


<?php
var_dump(\Time\Duration::fromNanoseconds(1_500_000_000));


   &example.outputs;


object(Time\Duration)#1 (3) {
  ["seconds"]=>
  int(1)
  ["nanoseconds"]=>
  int(500000000)
  ["negative"]=>
  bool(false)
}




   Measuring elapsed time with hrtime


<?php
$start = hrtime(true);
usleep(1000);
$elapsed = \Time\Duration::fromNanoseconds(hrtime(true) - $start);

var_dump($elapsed);


   &example.outputs.similar;


object(Time\Duration)#1 (3) {
  ["seconds"]=>
  int(0)
  ["nanoseconds"]=>
  int(1062541)
  ["negative"]=>
  bool(false)
}
